'use client';

import * as React from 'react';
import { motion, type Variants } from 'motion/react';

import {
  getVariants,
  useAnimateIconContext,
  IconWrapper,
  type IconProps,
} from '@animate-ui/react/icons';

type FilePlusProps = IconProps<keyof typeof animations>;

const animations = {
  default: {
    plus: {
      initial: { rotate: 0 },
      animate: { rotate: 90, transition: { duration: 0.5, ease: 'easeInOut' } },
    },
  } satisfies Record<string, Variants>,
} as const;

function IconComponent({ size, ...props }: FilePlusProps) {
  const { controls } = useAnimateIconContext();
  const variants = getVariants(animations);

  return (
    <motion.svg
      xmlns="http://www.w3.org/2000/svg"
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth={2}
      strokeLinecap="round"
      strokeLinejoin="round"
      {...props}
    >
      <path d="M6 22a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h8a2.4 2.4 0 0 1 1.704.706l3.588 3.588A2.4 2.4 0 0 1 20 8v12a2 2 0 0 1-2 2z" />
      <path d="M14 2v5a1 1 0 0 0 1 1h5" />
      <motion.g variants={variants.plus} initial="initial" animate={controls}>
        <path d="M9 15h6" />
        <path d="M12 18v-6" />
      </motion.g>
    </motion.svg>
  );
}

function FilePlus(props: FilePlusProps) {
  return <IconWrapper icon={IconComponent} {...props} />;
}

export {
  animations,
  FilePlus,
  FilePlus as FilePlusIcon,
  type FilePlusProps,
  type FilePlusProps as FilePlusIconProps,
};
